// This file is generated by AI.

// 对话者到角色的静默匹配。
//
// 依据来自三处 (按可信度降序):
// 1. 场景里该说话者出现过的 `-figureId=` (立绘 id 通常与角色一一对应);
// 2. 角色名与别名;
// 3. 旁白继承: 旁白沿用同场景上一条旁白所选的角色。
//
// 匹配是静默的: 不提供"匹配"按钮, 失败时仅表现为下拉框未选中,
// 由用户手动选择; 用户的手动选择会作为场景级覆盖被记住。

import type { Character, SayLine } from '../commands/voice';

export interface CharacterMatch {
  characterId: string | null;
  /** 匹配依据, 仅用于悬浮提示 */
  reason: 'figureId' | 'name' | 'alias' | 'override' | 'narration' | 'none';
}

/** 归一化字符串 (大小写、空白、全角空格) */
function normalize(value: string): string {
  return value.trim().toLowerCase().replace(/\s+/g, '');
}

/** 从对话列表中统计"说话者 -> 其出现过的立绘 id" */
export function figureIdsBySpeaker(dialogues: SayLine[]): Map<string, Set<string>> {
  const map = new Map<string, Set<string>>();
  for (const line of dialogues) {
    if (!line.speaker || !line.figureId) continue;
    const key = normalize(line.speaker);
    const set = map.get(key) ?? new Set<string>();
    set.add(line.figureId);
    map.set(key, set);
  }
  return map;
}

export interface MatchContext {
  characters: Character[];
  /** 场景级手动覆盖: 说话者 (归一化) -> 角色 id */
  overrides: Record<string, string>;
  /** 该场景中已确定归属的说话者 -> 角色 id (用于旁白继承) */
  resolved: Record<string, string>;
  figureIds: Map<string, Set<string>>;
}

/**
 * 为一条对话推断角色。
 *
 * `resolved` 由调用者在按行推进时维护, 因此本函数是纯函数, 便于测试。
 */
export function matchCharacter(line: SayLine, context: MatchContext): CharacterMatch {
  const enabled = context.characters.filter((character) => character.enabled);

  // 旁白: 不按说话者匹配, 交给调用者用"上一条旁白的角色"填充
  if (!line.speaker) {
    return { characterId: null, reason: 'narration' };
  }

  const speaker = normalize(line.speaker);

  const override = context.overrides[speaker];
  if (override && enabled.some((character) => character.id === override)) {
    return { characterId: override, reason: 'override' };
  }

  // 立绘 id 精确匹配: 角色别名中若命中该 figureId, 视为同一角色
  const figureIds = context.figureIds.get(speaker);
  if (figureIds && figureIds.size > 0) {
    for (const character of enabled) {
      const keys = [character.id, character.name, ...character.aliases].map(normalize);
      if ([...figureIds].some((figureId) => keys.includes(normalize(figureId)))) {
        return { characterId: character.id, reason: 'figureId' };
      }
    }
  }

  // 名称精确匹配
  for (const character of enabled) {
    if (normalize(character.name) === speaker) {
      return { characterId: character.id, reason: 'name' };
    }
  }

  // 别名精确匹配
  for (const character of enabled) {
    if (character.aliases.some((alias) => normalize(alias) === speaker)) {
      return { characterId: character.id, reason: 'alias' };
    }
  }

  return { characterId: null, reason: 'none' };
}

/**
 * 依次为整场景对话推断角色。
 *
 * 返回 `Map<对话行号, CharacterMatch>`。旁白继承规则: 若上一条**旁白**已有归属,
 * 则本条旁白沿用同一角色 (用户为旁白选定角色后, 后续旁白无需重复选择)。
 */
export function matchScene(
  dialogues: SayLine[],
  characters: Character[],
  overrides: Record<string, string> = {}
): Map<number, CharacterMatch> {
  const context: MatchContext = {
    characters,
    overrides,
    resolved: {},
    figureIds: figureIdsBySpeaker(dialogues),
  };

  const result = new Map<number, CharacterMatch>();
  let lastNarrationCharacter: string | null = null;

  for (const line of dialogues) {
    const match = matchCharacter(line, context);
    if (line.speaker === null) {
      // 旁白: 先看人工覆盖, 再沿用上一条旁白的角色
      const override = context.overrides[''];
      const chosen = override ?? lastNarrationCharacter;
      const valid = chosen && characters.some((character) => character.id === chosen && character.enabled);
      const resolved: CharacterMatch = valid
        ? { characterId: chosen, reason: override ? 'override' : 'narration' }
        : { characterId: null, reason: 'none' };
      result.set(line.line, resolved);
      if (resolved.characterId) lastNarrationCharacter = resolved.characterId;
      continue;
    }

    result.set(line.line, match);
    if (match.characterId) {
      context.resolved[normalize(line.speaker)] = match.characterId;
    }
  }

  return result;
}
